   352	    private static byte[] WithChunkLength(byte[] png, int length)
   353	    {
   354	        var copy = png.ToArray();
   355	        Span<byte> destination = copy.AsSpan(8, 4);
   356	        BinaryPrimitives.WriteInt32BigEndian(destination, length);
